/**
 * GET /api/auth/me   (Authorization: Bearer <session>, x-vinax-device?)
 *   → 200 { user }               the account as the database has it (schema 20: with `hasPassword`;
 *                                2.0: `admin: true` when its email is on Admins & Roles, so the app
 *                                can show its Admin link — the console still signs in on its own)
 *   → 200 { ok: true }           no database on this Worker: the session alone stands
 *   → 401 { error: 'signed_out' } bad session, or the account row is gone (deleted)
 *   → 401 { error: 'signed_out', reason: 'blocked' }      the owner blocked this person
 *   → 401 { error: 'signed_out', reason: 'device_signed_out' } the owner signed THIS
 *        device out (listeners.signed_out_at is after the session was issued)
 *   → 503 { error: 'unavailable' } the database did not answer
 * POST /api/auth/me { delete: true } → 200 { ok: true } — removes the account
 *   row and, with it, the synced backup. Usage events are anonymous and stay.
 *
 * The session check keeps the account current: last_seen is refreshed at
 * most every TOUCH_MS, and a proved device id (the header) links the device,
 * so a listener who ticked "share usage" after signing in is still one row
 * in the console. Best effort, after the answer.
 */
import { removeAccountFiles } from '../../_lib/ai/attachments';
import { bearer, readSession, readSessionClaims, type AuthEnv } from '../../_lib/googleAuth';
import { readJsonCapped } from '../../_lib/body';
import { rateLimitAsync } from '../../_lib/ratelimit';
import { db, dbConfigured, q, type DbEnv } from '../../_lib/db';
import { DEVICE_HEADER, verifiedIdentity, type IdentityEnv } from '../../_lib/identity';
import { accountFacts, accountOf, CORS, handleOf, json, linkDevice, publicUser, type AccountRow } from '../../_lib/authShared';
import { hasPassword } from '../../_lib/signIn';
import { adminRowOf, normEmail, type AdminSessionEnv } from '../../_lib/adminAuth';

type Env = AuthEnv & DbEnv & IdentityEnv & AdminSessionEnv;

/** How stale last_seen may get before a session check refreshes it. */
export const TOUCH_MS = 10 * 60_000;

export async function touchAccount(request: Request, env: Env, row: AccountRow): Promise<boolean> {
  const patch: Record<string, unknown> = {};
  const proved = await verifiedIdentity(env, request.headers.get(DEVICE_HEADER));
  if (proved && proved !== row.listener_id) patch.listener_id = proved;
  const last = Date.parse(row.last_seen ?? '');
  if (patch.listener_id || !Number.isFinite(last) || Date.now() - last > TOUCH_MS) {
    patch.last_seen = new Date().toISOString();
    Object.assign(patch, accountFacts(request));
  }
  // V2 — the device proving itself is this account's, whichever device the
  // account last linked (several devices fold into one console row).
  if (proved && patch.listener_id) await linkDevice(env, proved, row.id);
  if (!Object.keys(patch).length) return false;
  const r = await db.update(env, 'accounts', q().eq('id', row.id), patch);
  return r.ok;
}

/**
 * Console rebuild — did the owner sign this device out after the session was
 * issued? Only a PROVED device id counts (a forged header proves nothing).
 */
export async function deviceSignedOut(request: Request, env: Env, iat: number): Promise<boolean> {
  const proved = await verifiedIdentity(env, request.headers.get(DEVICE_HEADER));
  if (!proved) return false;
  const d = await db.one<{ signed_out_at: string | null }>(env, 'listeners', q().eq('id', proved).select('signed_out_at'));
  const at = d.ok && d.value?.signed_out_at ? Date.parse(d.value.signed_out_at) : NaN;
  return Number.isFinite(at) && at >= iat * 1000;
}

export const onRequestOptions = async (): Promise<Response> => new Response(null, { status: 204, headers: CORS });

export const onRequestGet = async (ctx: { request: Request; env: Env; waitUntil?: (p: Promise<unknown>) => void }): Promise<Response> => {
  const { request, env } = ctx;
  const claims = await readSessionClaims(env, bearer(request));
  if (!claims) return json({ error: 'signed_out' }, 401);
  const sub = claims.sub;
  if (!dbConfigured(env)) return json({ ok: true });
  const r = await accountOf(env, sub);
  if (!r.ok) return json({ error: 'unavailable' }, 503);
  if (!r.value) return json({ error: 'signed_out' }, 401);
  const row = r.value;
  if (row.blocked_at) return json({ error: 'signed_out', reason: 'blocked' }, 401);
  if (await deviceSignedOut(request, env, claims.iat)) return json({ error: 'signed_out', reason: 'device_signed_out' }, 401);
  const touch = touchAccount(request, env, row).catch(() => false);
  if (ctx.waitUntil) ctx.waitUntil(touch);
  else await touch;
  const email = normEmail(row.email);
  const [handle, password, adminRow] = await Promise.all([
    handleOf(env, row.listener_id),
    hasPassword(env, row.id),
    email ? adminRowOf(env, email).catch(() => null) : Promise.resolve(null),
  ]);
  return json({ user: { ...publicUser(row, handle), hasPassword: password, ...(adminRow ? { admin: true } : {}) } });
};

export const onRequestPost = async (ctx: { request: Request; env: Env }): Promise<Response> => {
  const { request, env } = ctx;
  const limited = await rateLimitAsync(request, 'auth-me', { capacity: 5, refillPerMinute: 5 }, env);
  if (limited) return limited;
  const sub = await readSession(env, bearer(request));
  if (!sub) return json({ error: 'signed_out' }, 401);
  const read = await readJsonCapped<{ delete?: unknown } | null>(request, 1_000);
  if (!read.ok || read.value?.delete !== true) return json({ error: 'bad_request' }, 400);
  if (!dbConfigured(env)) return json({ ok: true });
  // VinaX AI files live in Storage, not in a row that cascades: remove them first.
  await removeAccountFiles(env, sub);
  const r = await db.remove(env, 'accounts', q().eq('id', sub)); // the backup, chats and their rows cascade
  return r.ok ? json({ ok: true }) : json({ error: 'unavailable' }, 503);
};
