/**
 * Firebase Cloud Messaging (HTTP v1) sender — native Android background push,
 * so notifications arrive even when the app is fully closed (unlike the WebView
 * local-notification path, which only fires while the app is open).
 *
 * Requires FCM_SERVICE_ACCOUNT: the Firebase service-account JSON (the whole
 * file, as a string) set as a secret on the Worker (`vinax-api`; a Pages
 * secret is not seen by the Worker). No-op when unset, so the rest of the app
 * is unaffected until you configure it.
 */

/**
 * 13.7.3 — the Android channel, small icon and accent every push uses. The
 * app creates the channel at start-up (services/push/nativePush.ts) and the
 * manifest names the same three as FCM's defaults (scripts/patch-android.js),
 * so a push looks the same whether the app or FCM draws it. The icon must be a
 * white-on-transparent drawable: a full-colour launcher icon draws as a blob.
 */
export const FCM_CHANNEL_ID = 'vinax_picks';
export const FCM_SMALL_ICON = 'vinax_ic_notify';
export const FCM_ACCENT = '#FFA42E';
/** The colour VinaX mark a push shows when the owner attached no picture. */
export const FCM_LOGO_URL = 'https://www.vinaxmusic.online/icons/icon-512.png';
export interface FcmEnv {
  FCM_SERVICE_ACCOUNT?: string;
}

export function fcmConfigured(env: FcmEnv): boolean {
  return !!env.FCM_SERVICE_ACCOUNT;
}

interface ServiceAccount {
  client_email: string;
  private_key: string;
  project_id: string;
  token_uri?: string;
}

let cachedToken: { token: string; exp: number } | null = null;
// Coalesce concurrent JWT-sign + token-exchange requests. Without this, two
// parallel isolate calls would each do the RSA sign + POST to oauth2, double-
// billing the exchange until one finished and populated `cachedToken`
// (audit finding M17). Cleared on completion so a subsequent expiry-driven
// refresh runs again.
let inflightExchange: Promise<string | null> | null = null;

function b64url(bytes: ArrayBuffer | Uint8Array): string {
  const b = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  let s = '';
  for (let i = 0; i < b.length; i += 1) s += String.fromCharCode(b[i]);
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
function b64urlStr(str: string): string {
  return b64url(new TextEncoder().encode(str));
}
function pemToDer(pem: string): ArrayBuffer {
  const body = pem
    .replace(/-----BEGIN [^-]+-----/, '')
    .replace(/-----END [^-]+-----/, '')
    .replace(/\s+/g, '');
  const bin = atob(body);
  const buf = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i += 1) buf[i] = bin.charCodeAt(i);
  return buf.buffer;
}

/** Exchange the service account for a short-lived OAuth2 access token (cached). */
async function accessToken(sa: ServiceAccount): Promise<string | null> {
  const now = Math.floor(Date.now() / 1000);
  if (cachedToken && cachedToken.exp > now + 60) return cachedToken.token;
  if (inflightExchange) return inflightExchange;
  inflightExchange = (async (): Promise<string | null> => {
    try {
      const tokenUri = sa.token_uri || 'https://oauth2.googleapis.com/token';
      const header = b64urlStr(JSON.stringify({ alg: 'RS256', typ: 'JWT' }));
      const claims = b64urlStr(
        JSON.stringify({
          iss: sa.client_email,
          scope: 'https://www.googleapis.com/auth/firebase.messaging',
          aud: tokenUri,
          iat: now,
          exp: now + 3600,
        }),
      );
      const unsigned = `${header}.${claims}`;
      const key = await crypto.subtle.importKey(
        'pkcs8',
        pemToDer(sa.private_key),
        { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' },
        false,
        ['sign'],
      );
      const sig = await crypto.subtle.sign('RSASSA-PKCS1-v1_5', key, new TextEncoder().encode(unsigned));
      const jwt = `${unsigned}.${b64url(sig)}`;
      const res = await fetch(tokenUri, {
        method: 'POST',
        headers: { 'content-type': 'application/x-www-form-urlencoded' },
        body: `grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer&assertion=${jwt}`,
      });
      if (!res.ok) return null;
      const d = (await res.json()) as { access_token?: string; expires_in?: number };
      if (!d.access_token) return null;
      cachedToken = { token: d.access_token, exp: now + (d.expires_in ?? 3600) };
      return d.access_token;
    } catch {
      return null;
    } finally {
      inflightExchange = null;
    }
  })();
  return inflightExchange;
}

/**
 * 12.2.1 — does FCM_SERVICE_ACCOUNT work? Names only, never the key: which
 * project it belongs to, whether Google issues a token for it, and how FCM
 * answers a validate-only message to a made-up device (nothing is delivered).
 * A working setup answers `fcm: 'ok'` — FCM checked the message and refused
 * only the fake device.
 */
export async function checkFcm(env: FcmEnv): Promise<{ configured: boolean; project: string | null; token: boolean; fcm: 'ok' | 'denied' | 'error' | 'skipped'; detail: string | null }> {
  if (!env.FCM_SERVICE_ACCOUNT) return { configured: false, project: null, token: false, fcm: 'skipped', detail: null };
  let sa: ServiceAccount;
  try {
    sa = JSON.parse(env.FCM_SERVICE_ACCOUNT) as ServiceAccount;
  } catch {
    return { configured: true, project: null, token: false, fcm: 'skipped', detail: 'not valid JSON' };
  }
  const project = typeof sa.project_id === 'string' ? sa.project_id : null;
  cachedToken = null;
  const at = await accessToken(sa);
  if (!at || !project) return { configured: true, project, token: false, fcm: 'skipped', detail: 'Google refused the service account' };
  try {
    const res = await fetch(`https://fcm.googleapis.com/v1/projects/${project}/messages:send`, {
      method: 'POST',
      headers: { authorization: `Bearer ${at}`, 'content-type': 'application/json' },
      body: JSON.stringify({ validate_only: true, message: { token: 'vinax-fcm-self-test-not-a-device', notification: { title: 'test', body: 'test' } } }),
      signal: AbortSignal.timeout(10_000),
    });
    const j = (await res.json().catch(() => null)) as { error?: { status?: string; message?: string; details?: Array<{ errorCode?: string }> } } | null;
    const code = j?.error?.details?.find((d) => d.errorCode)?.errorCode ?? j?.error?.status ?? null;
    if (res.ok || res.status === 400 || res.status === 404) return { configured: true, project, token: true, fcm: 'ok', detail: code };
    return { configured: true, project, token: true, fcm: res.status === 401 || res.status === 403 ? 'denied' : 'error', detail: `${res.status} ${code ?? ''}`.trim() };
  } catch {
    return { configured: true, project, token: true, fcm: 'error', detail: 'no answer' };
  }
}

export interface FcmMessage {
  title: string;
  body: string;
  link?: string;
  /** Console rebuild: a picture for the notification (https only) and the notifications row id (tap counting). */
  image?: string | null;
  id?: number | null;
}

/**
 * Send a notification to the given device tokens. Returns how many were
 * delivered and which tokens are dead (unregistered) so the caller can prune
 * them. Best-effort, never throws.
 *
 * Fan-out runs concurrently with a bounded worker pool (audit finding M-SRV-3
 * — the old sequential loop tripped the Pages Functions 30 s wall clock at
 * scale) and every per-token fetch carries a 10 s abort so one slow upstream
 * can't stall the pool.
 */
export interface FcmResult {
  sent: number;
  /** Tokens FCM says no longer exist — safe to deactivate. */
  dead: string[];
  /** Why the rest did not go, by FCM error code (or HTTP status / 'timeout'). */
  failed: Record<string, number>;
  /** Set when nothing could be sent at all: the secret or Google refused it. */
  error: string | null;
}

/**
 * Is this FCM refusal about the token itself (the app was uninstalled, the
 * token rotated or was never valid)? Only then is the device pruned. A plain
 * 400 is NOT enough: a malformed message answers 400 for every device, and
 * treating that as "dead" once deactivated every Android device at once.
 */
function tokenIsDead(status: number, code: string | null, message: string): boolean {
  if (status === 404 || code === 'UNREGISTERED') return true;
  return status === 400 && code === 'INVALID_ARGUMENT' && /registration token/i.test(message);
}

export async function sendFcm(env: FcmEnv, tokens: string[], msg: FcmMessage): Promise<FcmResult> {
  const dead: string[] = [];
  const failed: Record<string, number> = {};
  if (!env.FCM_SERVICE_ACCOUNT) return { sent: 0, dead, failed, error: 'not_configured' };
  if (!tokens.length) return { sent: 0, dead, failed, error: null };
  let sa: ServiceAccount;
  try {
    sa = JSON.parse(env.FCM_SERVICE_ACCOUNT) as ServiceAccount;
  } catch {
    return { sent: 0, dead, failed, error: 'bad_service_account_json' };
  }
  const at = await accessToken(sa);
  if (!at) return { sent: 0, dead, failed, error: 'google_refused_service_account' };
  const url = `https://fcm.googleapis.com/v1/projects/${sa.project_id}/messages:send`;

  const sendOne = async (token: string): Promise<'ok' | 'dead' | string> => {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 10_000);
    try {
      const res = await fetch(url, {
        method: 'POST',
        headers: { authorization: `Bearer ${at}`, 'content-type': 'application/json' },
        body: JSON.stringify({
          message: {
            token,
            // 1.12 — a push with no picture of its own carries the VinaX logo:
            // Android shows it as the notification's large icon (and as the
            // picture when expanded), so every push is recognisably VinaX.
            notification: { title: msg.title.slice(0, 120), body: (msg.body || '').slice(0, 240), image: msg.image && /^https:\/\//.test(msg.image) ? msg.image : FCM_LOGO_URL },
            // The title and body ride in `data` too, so a build that handles the
            // message itself (a data listener) can draw the same notification.
            data: { link: msg.link || '/', title: msg.title.slice(0, 120), body: (msg.body || '').slice(0, 240), ...(msg.image && /^https:\/\//.test(msg.image) ? { image: msg.image } : {}), ...(msg.id ? { id: String(msg.id) } : {}) },
            android: {
              // 1.12 — delivered while the app is closed, not held until it opens:
              // high priority wakes the device out of Doze for this message, the
              // notification itself is marked high so Android shows it at once
              // (a normal one can sit silently in the tray), and a phone that is
              // off keeps it for a day instead of dropping it after a while.
              priority: 'high',
              ttl: '86400s',
              direct_boot_ok: true,
              notification: {
                channel_id: FCM_CHANNEL_ID, icon: FCM_SMALL_ICON, color: FCM_ACCENT, default_sound: true, default_vibrate_timings: true,
                notification_priority: 'PRIORITY_HIGH', visibility: 'PUBLIC',
              },
            },
          },
        }),
        signal: ctrl.signal,
      });
      if (res.ok) return 'ok';
      const j = (await res.json().catch(() => null)) as { error?: { status?: string; message?: string; details?: Array<{ errorCode?: string }> } } | null;
      const code = j?.error?.details?.find((d) => d.errorCode)?.errorCode ?? j?.error?.status ?? null;
      if (tokenIsDead(res.status, code, j?.error?.message ?? '')) return 'dead';
      return code ?? String(res.status);
    } catch {
      return 'timeout';
    } finally {
      clearTimeout(timer);
    }
  };

  // Bounded-concurrency worker pool. Duplicated locally so this helper stays
  // self-contained.
  const limit = Math.min(8, tokens.length);
  let cursor = 0;
  let sent = 0;
  const workers = Array.from({ length: limit }, async () => {
    while (true) {
      const i = cursor++;
      if (i >= tokens.length) return;
      const outcome = await sendOne(tokens[i]);
      if (outcome === 'ok') sent += 1;
      else if (outcome === 'dead') dead.push(tokens[i]);
      else failed[outcome] = (failed[outcome] ?? 0) + 1;
    }
  });
  await Promise.all(workers);
  return { sent, dead, failed, error: null };
}
